package android.graphics;public class Path {public enum Direction{CW}public java.awt.geom.Path2D.Float shape=new java.awt.geom.Path2D.Float();public void addCircle(float x,float y,float r,Direction d){shape.append(new java.awt.geom.Ellipse2D.Float(x-r,y-r,r*2,r*2),false);}public void moveTo(float x,float y){shape.moveTo(x,y);}public void lineTo(float x,float y){shape.lineTo(x,y);}public void close(){shape.closePath();}}
